    if(['login','register','reset'].includes(mode)){password=field(form,mode==='reset'?'Nova senha':'Senha','password','','password');password.required=true;password.minLength=mode==='login'?1:12;password.maxLength=200;password.autocomplete=mode==='login'?'current-password':'new-password';if(mode!=='login')form.append(node('small','Use pelo menos 12 caracteres.'));}
